Object.assign(window.POC_SRC,{"turnout-signal": "\"\"\"\nTurnout Signal - proof of concept (pure Python, standard library only).\n\nClaim A (history beats talk): weighting poll respondents by a turnout probability learned from\n  their own voting history (from the voter file) predicts the electorate better than asking\n  \"how likely are you to vote, 1 to 10?\".\nClaim B (linkage): the method only works for respondents who can be matched to the voter file.\n  The lab measures who gets matched, and who does not.\nClaim C (the limit): when people with no voting habit suddenly turn out (a late mobilisation),\n  a model that learned from history gives them little weight, by design.\nClaim D (portability): in a country with compulsory voting and no public record of who voted,\n  there is no history to learn from.\n\nFour labs (run(scenario) for the website):\n  1. steady   - an ordinary midterm: screen vs voter-file model\n  2. linkage  - who can be matched to the file, by habit and age\n  3. mobilize - the same poll, a late mobilisation of non-habitual voters\n  4. nofile   - Brazil-like: voting is compulsory, no individual history is public\n\nHONESTY: the electorate, the voter file and the answers are SYNTHETIC (fixed seed 2026).\n  Match rates and turnout probabilities are assumptions of the order reported in U.S. studies\n  of commercial voter files (most respondents match, habitual voters match more often);\n  they are not measured here. The matching, the turnout model and the weighting are real code.\n\"\"\"\nimport random, json\n\nSEED = 2026\nREPS = 8\n\ndef build(seed=SEED, n=30000, mobilize=False):\n    rng = random.Random(seed); P = []\n    for i in range(n):\n        e = \"deg\" if rng.random() < 0.36 else \"nodeg\"\n        a = \"young\" if rng.random() < 0.42 else \"old\"\n        r = \"urban\" if rng.random() < 0.62 else \"rural\"\n        lean = 0.5 + (0.12 if e == \"deg\" else -0.07) + (0.08 if a == \"young\" else -0.05) + (0.10 if r == \"urban\" else -0.16)\n        blue = rng.random() < lean\n        habit = rng.random() < (0.38 + (0.22 if a == \"old\" else 0) + (0.12 if e == \"deg\" else 0) + (0.10 if not blue else 0))   # in midterms, the habitual electorate leans red\n        hist = sum(rng.random() < (0.85 if habit else 0.2) for _ in range(3))   # voted in 0..3 of the last three elections\n        p_vote = 0.18 + 0.70 * habit\n        says = max(1, min(10, round(10 * p_vote + 1.8 + rng.gauss(0, 2.4))))   # optimistic, or not quite honest (the report)\n        late = False\n        if mobilize:\n            if blue and not habit: p_vote += 0.18; late = True\n            if (not blue) and habit: p_vote -= 0.08\n        votes = rng.random() < p_vote\n        in_file = rng.random() < ((0.93 if habit else 0.70) - (0.08 if a == \"young\" else 0))   # moved, new, or never registered: no match\n        p_resp = 0.020 * (1.7 if e == \"deg\" else 0.8) * (1.3 if a == \"old\" else 0.8) * (1.15 if habit else 0.75) * (1.07 if blue else 0.93)\n        P.append(dict(cell=(e, a, r), blue=blue, habit=habit, hist=hist, votes=votes, says=says, in_file=in_file, p_resp=p_resp, late=late))\n    return P\n\ndef truth(P):\n    v = [p for p in P if p[\"votes\"]]; return 100 * sum(p[\"blue\"] for p in v) / len(v)\n\ndef poll(P, rng, attempts=52000):\n    return [p for p in (rng.choice(P) for _ in range(attempts)) if rng.random() < p[\"p_resp\"]]\n\ndef rake(resp, P, rounds=10):\n    w = [1.0] * len(resp); tp = len(P); pops = [{}, {}, {}]\n    for p in P:\n        for k in range(3): pops[k][p[\"cell\"][k]] = pops[k].get(p[\"cell\"][k], 0) + 1\n    for _ in range(rounds):\n        for k in range(3):\n            smp = {}\n            for i, p in enumerate(resp): smp[p[\"cell\"][k]] = smp.get(p[\"cell\"][k], 0) + w[i]\n            ts = sum(w)\n            for i, p in enumerate(resp): v = p[\"cell\"][k]; w[i] *= (pops[k][v] / tp) / (smp[v] / ts)\n    return w\n\ndef turnout_model(P):\n    \"\"\"Learn P(vote | history) from the file: the share who voted last time, by number of past votes.\"\"\"\n    tab = {}\n    for p in P:\n        if p[\"in_file\"]:\n            t = tab.setdefault(p[\"hist\"], [0, 0]); t[0] += 1; t[1] += p[\"habit\"]   # last time's turnout ~ habit\n    return {h: 0.18 + 0.70 * (v[1] / v[0]) for h, v in tab.items()}\n\ndef est_screen(resp, w):\n    num = sum(wi for p, wi in zip(resp, w) if p[\"says\"] >= 9 and p[\"blue\"]); den = sum(wi for p, wi in zip(resp, w) if p[\"says\"] >= 9)\n    return 100 * num / den\n\ndef est_model(resp, w, model):\n    num = den = 0.0\n    for p, wi in zip(resp, w):\n        if not p[\"in_file\"]: continue                 # unmatched: no history, no weight\n        q = model[p[\"hist\"]] * wi; den += q; num += q * p[\"blue\"]\n    return 100 * num / den\n\ndef _avg(rows):\n    return {k: round(sum(r[k] for r in rows) / len(rows), 1) for k in rows[0]}\n\ndef turnout_only(P, M):\n    \"\"\"The turnout question alone: apply both methods to EVERYONE (no non-response), compare to the truth.\"\"\"\n    w = [1.0] * len(P); t = truth(P)\n    return round(est_screen(P, w) - t, 1), round(est_model(P, w, M) - t, 1)\n\ndef lab_steady(mobilize=False):\n    P = build(mobilize=mobilize); M = turnout_model(P); rows = []\n    ts, tm = turnout_only(P, M)\n    for k in range(REPS):\n        resp = poll(P, random.Random(SEED + 100 + k)); w = rake(resp, P); t = truth(P)\n        a = est_screen(resp, w); b = est_model(resp, w, M)\n        rows.append(dict(truth=t, screen=a, model=b, err_screen=a - t, err_model=b - t, n=len(resp),\n                         matched=100 * sum(p[\"in_file\"] for p in resp) / len(resp)))\n    out = _avg(rows); out.update(turnout_screen=ts, turnout_model=tm); return out\n\ndef lab_linkage():\n    P = build(); resp = []\n    for k in range(REPS): resp += poll(P, random.Random(SEED + 100 + k))\n    g = lambda f: round(100 * sum(p[\"in_file\"] for p in resp if f(p)) / max(1, sum(1 for p in resp if f(p))), 1)\n    late_voters = [p for p in P if p[\"votes\"] and not p[\"habit\"]]\n    return dict(all=g(lambda p: True), habitual=g(lambda p: p[\"habit\"]), non_habitual=g(lambda p: not p[\"habit\"]),\n                young=g(lambda p: p[\"cell\"][1] == \"young\"), old=g(lambda p: p[\"cell\"][1] == \"old\"),\n                nonhabit_share_of_voters=round(100 * len(late_voters) / sum(p[\"votes\"] for p in P), 1))\n\ndef lab_nofile():\n    \"\"\"Brazil-like: everyone 18-70 must vote; turnout is high and flat; no public individual history.\"\"\"\n    return dict(file_rows=0, history_columns=0, model_can_train=False,\n                note=\"compulsory voting (TSE: literate citizens aged 18-70); who voted is not a public per-person record\")\n\ndef run_all():\n    return {\"steady\": lab_steady(), \"linkage\": lab_linkage(), \"mobilize\": lab_steady(mobilize=True), \"nofile\": lab_nofile()}\n\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: steady | linkage | mobilize | nofile.\"\"\"\n    ev, ck = [], []\n    if sc == \"steady\":\n        r = lab_steady()\n        ev += [_ev(\"R\", \"S\", \"screen\", f\"the turnout question alone (everyone, no non-response): the 1-10 screen misses the electorate by {r['turnout_screen']:+} points\", f\"{r['turnout_screen']:+}\", bad=True),\n               _ev(\"R\", \"F\", \"match\", f\"{r['matched']}% of poll respondents matched to the voter file\", f\"{r['matched']}%\"),\n               _ev(\"F\", \"M\", \"model\", f\"the history model on the same question: {r['turnout_model']:+} points\", f\"{r['turnout_model']:+}\", ok=abs(r['turnout_model']) < abs(r['turnout_screen'])),\n               _ev(\"M\", \"E\", \"poll\", f\"in a real poll (truth {r['truth']}%): screen {r['err_screen']:+}, model {r['err_model']:+}; the +2 or so of who answers is still there, and it is not the model's job\", f\"{r['err_model']:+}\", bad=abs(r['err_model']) > 1.5)]\n        ck += [[\"model_beats_screen\", abs(r[\"turnout_model\"]) < abs(r[\"turnout_screen\"])], [\"match_measured\", True]]\n    elif sc == \"linkage\":\n        r = lab_linkage()\n        ev += [_ev(\"R\", \"F\", \"all\", f\"matched to the file: {r['all']}% of respondents\", f\"{r['all']}%\"),\n               _ev(\"F\", \"F\", \"habit\", f\"habitual voters {r['habitual']}%, non-habitual {r['non_habitual']}%\", f\"{r['habitual']}% / {r['non_habitual']}%\", bad=r['habitual'] - r['non_habitual'] > 10),\n               _ev(\"F\", \"F\", \"age\", f\"older {r['old']}%, younger {r['young']}%\", f\"{r['old']}% / {r['young']}%\", bad=True),\n               _ev(\"F\", \"M\", \"who\", f\"non-habitual voters are {r['nonhabit_share_of_voters']}% of those who vote; they are the least matched\", f\"{r['nonhabit_share_of_voters']}%\", bad=True)]\n        ck += [[\"linkage_measured\", True], [\"gap_by_habit\", r[\"habitual\"] > r[\"non_habitual\"]]]\n    elif sc == \"mobilize\":\n        s = lab_steady(); r = lab_steady(mobilize=True)\n        ev += [_ev(\"R\", \"M\", \"late\", f\"a late mobilisation of non-habitual blue voters; truth moves to {r['truth']}%; on the turnout question alone the model now misses by {r['turnout_model']:+}\", f\"{r['truth']}%\"),\n               _ev(\"F\", \"M\", \"model\", f\"the history model: {r['model']}% (error {r['err_model']:+}; in a steady year {s['err_model']:+})\", f\"{r['err_model']:+}\", bad=True),\n               _ev(\"R\", \"S\", \"screen\", f\"the 1-10 screen: {r['screen']}% (error {r['err_screen']:+})\", f\"{r['err_screen']:+}\", bad=True),\n               _ev(\"M\", \"E\", \"why\", \"the model is right about the past: these people did not vote before. That is exactly why it misses them now\", \"ההיסטוריה\", bad=True)]\n        ck += [[\"mobilization_measured\", True], [\"model_misses_new_voters\", r[\"err_model\"] < -1.5]]\n    elif sc == \"nofile\":\n        r = lab_nofile()\n        ev += [_ev(\"R\", \"F\", \"brazil\", \"Brazil: voting is compulsory for literate citizens aged 18-70\", \"חובה\"),\n               _ev(\"F\", \"F\", \"rows\", f\"rows of individual voting history available to a pollster: {r['file_rows']}\", \"0 שורות\", bad=True),\n               _ev(\"F\", \"M\", \"train\", \"the turnout model has nothing to learn from; the feature cannot run here\", \"אין מודל\", bad=True),\n               _ev(\"M\", \"E\", \"open\", \"open question for the spec: what is the signal in a country without a file?\", \"שאלה פתוחה\")]\n        ck += [[\"portability_checked\", True]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1))\n", "synthetic-respondents": "\"\"\"\nSynthetic Respondents - proof of concept (pure Python, standard library only).\n\nClaim A (fill the gaps): for every demographic cell that answers too little, generate \"silicon\"\n  respondents and ask them the poll question. If they answer like the real people in that cell,\n  the missing voices are filled at almost no cost.\nClaim B (stability): the synthetic answers are stable, cheap and available overnight.\nTest C (change): what happens when the electorate CHANGES after the training data was written\n  (a late mobilisation, a swing inside one cell)?\nTest D (circularity): how many real, fresh respondents are needed to recalibrate the synthetic ones?\n\nFour labs (run(scenario) for the website):\n  1. steady    - 2026 looks like 2024: synthetic vs. a real poll\n  2. shift     - 2026 moves: a mobilisation and a swing in one cell\n  3. variance  - how much the answers inside a cell differ: people vs. silicon\n  4. calibrate - fresh human answers needed to fix the silicon, and what that costs\n\nHONESTY: no language model runs in this lab. A language model conditioned on a profile reproduces\n  what its training text says people like that think (Argyle et al., 2023), with less variety\n  than real people (Bisbee et al., 2024). The lab SIMULATES exactly that behaviour: a silicon\n  respondent answers with the cell's 2024 opinion, pulled slightly toward the overall average,\n  plus a small noise. Everything is synthetic (fixed seed 2026). The lab tests the idea's logic,\n  not any specific model.\n\"\"\"\nimport random, json, math\n\nSEED = 2026\nCELLS = [(e, a, r) for e in (\"deg\", \"nodeg\") for a in (\"young\", \"old\") for r in (\"urban\", \"rural\")]\n\ndef build(seed, n=30000, mobilize=False, swing=0.0):\n    rng = random.Random(seed); P = []\n    for i in range(n):\n        e = \"deg\" if rng.random() < 0.36 else \"nodeg\"\n        a = \"young\" if rng.random() < 0.42 else \"old\"\n        r = \"urban\" if rng.random() < 0.62 else \"rural\"\n        lean = 0.5 + (0.12 if e == \"deg\" else -0.07) + (0.08 if a == \"young\" else -0.05) + (0.10 if r == \"urban\" else -0.16)\n        if (e, a, r) == (\"nodeg\", \"young\", \"urban\"): lean += swing        # a swing inside one cell (like a shift among young voters)\n        opinion = max(0.0, min(1.0, rng.gauss(lean, 0.22)))                # a 0..1 scale: how warm toward blue\n        blue = rng.random() < lean\n        habit = rng.random() < (0.38 + (0.22 if a == \"old\" else 0) + (0.12 if e == \"deg\" else 0))\n        p_vote = 0.18 + 0.70 * habit\n        if mobilize and blue and not habit: p_vote += 0.18\n        P.append(dict(cell=(e, a, r), blue=blue, opinion=opinion, votes=rng.random() < p_vote,\n                      p_resp=0.020 * (1.7 if e == \"deg\" else 0.8) * (1.3 if a == \"old\" else 0.8) * (1.15 if habit else 0.75) * (1.07 if blue else 0.93)))\n    return P\n\ndef truth(P):\n    v = [p for p in P if p[\"votes\"]]; return 100 * sum(p[\"blue\"] for p in v) / len(v)\n\ndef cell_table(P, voters_only=True):\n    t = {}\n    for p in P:\n        if voters_only and not p[\"votes\"]: continue\n        c = t.setdefault(p[\"cell\"], [0, 0]); c[0] += 1; c[1] += p[\"blue\"]\n    return t\n\nTRAIN = None\ndef training():\n    \"\"\"What the 'model' learned: 2024's cell opinions and 2024's electorate (a different seed: another year).\"\"\"\n    global TRAIN\n    if TRAIN is None: TRAIN = cell_table(build(SEED - 2))\n    return TRAIN\n\ndef silicon(n_per_cell, rng):\n    \"\"\"Silicon respondents: the 2024 cell share, pulled 15% toward the overall mean, with little noise.\"\"\"\n    T = training(); tot = sum(v[0] for v in T.values()); mean = sum(v[1] for v in T.values()) / tot\n    out = {}\n    for c, (n, b) in T.items():\n        p = 0.85 * (b / n) + 0.15 * mean\n        out[c] = [max(0, min(1, rng.gauss(p, 0.06))) for _ in range(n_per_cell)]\n    return out, {c: v[0] / tot for c, v in T.items()}      # opinions + the 2024 electorate mix\n\ndef est_silicon(rng):\n    \"\"\"Each silicon respondent 'votes' blue with its own probability (like sampling a model's answer).\"\"\"\n    S, mix = silicon(200, rng)\n    return 100 * sum(mix[c] * (sum(1 for x in S[c] if rng.random() < x) / len(S[c])) for c in CELLS)\n\ndef est_poll(P, rng, attempts=52000):\n    resp = [p for p in (rng.choice(P) for _ in range(attempts)) if rng.random() < p[\"p_resp\"]]\n    shares = {}\n    for p in P: shares[p[\"cell\"]] = shares.get(p[\"cell\"], 0) + 1\n    est = 0.0\n    for c in CELLS:\n        a = [p for p in resp if p[\"cell\"] == c]\n        if a: est += shares[c] / len(P) * sum(p[\"blue\"] for p in a) / len(a)\n    return 100 * est, len(resp)\n\ndef _lab(mobilize=False, swing=0.0, reps=6):\n    P = build(SEED, mobilize=mobilize, swing=swing); t = truth(P); rs, rp, n = [], [], 0\n    for k in range(reps):\n        rs.append(est_silicon(random.Random(SEED + 10 + k)) - t)\n        e, m = est_poll(P, random.Random(SEED + 100 + k)); rp.append(e - t); n += m\n    return dict(truth=round(t, 1), err_silicon=round(sum(rs) / reps, 1), err_poll=round(sum(rp) / reps, 1), n_poll=n // reps)\n\ndef lab_variance():\n    P = build(SEED); rng = random.Random(SEED + 5); S, _ = silicon(400, rng); rows = []\n    for c in CELLS:\n        real = [p[\"opinion\"] for p in P if p[\"cell\"] == c]\n        mr = sum(real) / len(real); vr = sum((x - mr) ** 2 for x in real) / len(real)\n        ms = sum(S[c]) / len(S[c]); vs = sum((x - ms) ** 2 for x in S[c]) / len(S[c])\n        rows.append(vs / vr)\n    real_ext = 100 * sum(1 for p in P if p[\"opinion\"] < 0.15 or p[\"opinion\"] > 0.85) / len(P)\n    sil_ext = 100 * sum(1 for c in CELLS for x in S[c] if x < 0.15 or x > 0.85) / (400 * len(CELLS))\n    return dict(variance_ratio=round(sum(rows) / len(rows), 2), strong_real=round(real_ext, 1), strong_silicon=round(sil_ext, 1))\n\ndef lab_calibrate():\n    \"\"\"To recalibrate each cell to within ~3 points (95%), each cell needs about 1/(0.03/1.96)^2 * p(1-p) fresh people.\"\"\"\n    per_cell = math.ceil((1.96 / 0.03) ** 2 * 0.25)\n    return dict(per_cell=per_cell, cells=len(CELLS), total=per_cell * len(CELLS), typical_poll=1000)\n\ndef run_all():\n    return {\"steady\": _lab(), \"shift\": _lab(mobilize=True, swing=0.10), \"variance\": lab_variance(), \"calibrate\": lab_calibrate()}\n\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: steady | shift | variance | calibrate.\"\"\"\n    ev, ck = [], []\n    if sc == \"steady\":\n        r = _lab()\n        ev += [_ev(\"T\", \"L\", \"train\", \"the model 'read' 2024: what each kind of voter said, and who voted\", \"2024\"),\n               _ev(\"L\", \"S\", \"gen\", \"1,600 silicon respondents, 200 per cell, overnight, at almost no cost\", \"1,600 סינתטיים\", ok=True),\n               _ev(\"S\", \"E\", \"est\", f\"silicon estimate: error {r['err_silicon']:+} points (truth {r['truth']}%)\", f\"{r['err_silicon']:+}\", ok=abs(r['err_silicon']) < 2),\n               _ev(\"P\", \"E\", \"poll\", f\"a real poll of {r['n_poll']} people, same week: error {r['err_poll']:+}\", f\"{r['err_poll']:+}\")]\n        ck += [[\"silicon_runs\", True], [\"steady_close\", abs(r[\"err_silicon\"]) < 2]]\n    elif sc == \"shift\":\n        s = _lab(); r = _lab(mobilize=True, swing=0.10)\n        ev += [_ev(\"T\", \"L\", \"train\", \"same training: 2024\", \"2024\"),\n               _ev(\"E\", \"E\", \"change\", f\"2026 moves: a late mobilisation, and young urban voters without a degree swing 10 points; truth {r['truth']}%\", f\"{r['truth']}%\"),\n               _ev(\"S\", \"E\", \"est\", f\"silicon: error {r['err_silicon']:+} (in a steady year {s['err_silicon']:+}); it answers like 2024 because that is all it knows\", f\"{r['err_silicon']:+}\", bad=True),\n               _ev(\"P\", \"E\", \"poll\", f\"a real poll: error {r['err_poll']:+}; it is noisy and biased, but the people in it live in 2026\", f\"{r['err_poll']:+}\", ok=abs(r['err_poll']) < abs(r['err_silicon']))]\n        ck += [[\"shift_measured\", True], [\"poll_beats_silicon_on_change\", abs(r[\"err_poll\"]) < abs(r[\"err_silicon\"])]]\n    elif sc == \"variance\":\n        r = lab_variance()\n        ev += [_ev(\"P\", \"E\", \"real\", f\"real people: {r['strong_real']}% hold a strong view at either end of the scale\", f\"{r['strong_real']}%\"),\n               _ev(\"S\", \"E\", \"silicon\", f\"silicon: the spread of views inside a cell is {r['variance_ratio']} of the real spread\", f\"x{r['variance_ratio']}\", bad=r['variance_ratio'] < 0.5),\n               _ev(\"S\", \"E\", \"strong\", f\"silicon with a strong view: {r['strong_silicon']}%; everyone sounds like the average of their group\", f\"{r['strong_silicon']}%\", bad=True)]\n        ck += [[\"variance_measured\", True], [\"too_uniform\", r[\"variance_ratio\"] < 0.5]]\n    elif sc == \"calibrate\":\n        r = lab_calibrate()\n        ev += [_ev(\"E\", \"L\", \"need\", f\"to recalibrate each cell within about 3 points you need ~{r['per_cell']} fresh people per cell\", f\"{r['per_cell']} לתא\"),\n               _ev(\"L\", \"P\", \"total\", f\"{r['cells']} cells x {r['per_cell']} = {r['total']:,} fresh human answers\", f\"{r['total']:,}\", bad=True),\n               _ev(\"P\", \"E\", \"circle\", f\"that is several times a typical poll (~{r['typical_poll']}): to fix the silicon, you must first run the poll it was meant to replace\", \"מעגל\", bad=True)]\n        ck += [[\"circularity_measured\", True]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1))\n", "second-call": "\"\"\"\nSecond Call - proof of concept (pure Python, standard library only).\n\nClaim A (monitor): while a poll is in the field, the system can see WHO is missing, cell by cell,\n  using only what is known about everyone it tried to reach (area, age band, education band,\n  how many attempts, which channel), and sum it up in one number. The labs report the coefficient\n  of variation (CV) of the response rates across cells, the companion of the R-indicator\n  (Schouten, Cobben & Bethlehem, 2009). CV 0 (or R = 1) = everyone answers at the same rate.\nClaim B (respond): moving the remaining attempts, channels and incentives toward the cells that\n  answer least lowers the CV (raises R) and lowers the error, at the same budget.\nClaim C (anchor): a small, expensive, truly random \"anchor\" sample with heavy follow-up has a much\n  smaller partisan gap in who answers. Calibrating the cheap panel to the anchor's recalled past\n  vote removes most of the bias that demographic weights alone cannot see.\nClaim D (late movers): a second short wave in the last week catches part of a late mobilisation\n  that a single wave two weeks out cannot see.\n\nFour labs (run(scenario) for the website):\n  1. static     - the usual way: fixed effort, rake on age, education and area\n  2. responsive - the same budget, re-allocated every 6 hours by the R-indicator\n  3. anchor     - plus an 800-person random anchor (from about 2,200 sampled addresses), and calibration to its recalled vote\n  4. mobilize   - a late mobilisation (like Brazil's run-off): one wave vs. a second wave\n\nHONESTY: the electorate, people, answers and turnout are SYNTHETIC (fixed seed 2026), built so that\n  the two mechanisms in the report exist: (1) within every demographic cell, \"blue\" supporters answer\n  more often than \"red\" ones (non-response bias); (2) who turns out can change late (mobilisation).\n  The sizes of these effects are assumptions, chosen to be of the order the report describes\n  (a few points), not measured. The monitoring, the R-indicator, the re-allocation and the\n  calibration are real code.\n\"\"\"\nimport random, json, math\n\nSEED = 2026\nCELLS = [(e, a, r) for e in (\"deg\", \"nodeg\") for a in (\"young\", \"old\") for r in (\"urban\", \"rural\")]\n\ndef cell_name(c):\n    return {\"deg\": \"תואר\", \"nodeg\": \"בלי תואר\", \"young\": \"צעירים\", \"old\": \"מבוגרים\", \"urban\": \"עיר\", \"rural\": \"כפר\"}[c[0]] + \" · \" + \\\n           {\"young\": \"צעירים\", \"old\": \"מבוגרים\"}[c[1]] + \" · \" + {\"urban\": \"עיר\", \"rural\": \"כפר\"}[c[2]]\n\ndef build_population(seed=SEED, n=30000, mobilize=False):\n    \"\"\"Everyone: cell, blue/red, habitual voter or not, response propensities, and whether they vote.\"\"\"\n    rng = random.Random(seed)\n    P = []\n    for i in range(n):\n        e = \"deg\" if rng.random() < 0.36 else \"nodeg\"\n        a = \"young\" if rng.random() < 0.42 else \"old\"\n        r = \"urban\" if rng.random() < 0.62 else \"rural\"\n        lean = 0.5 + (0.12 if e == \"deg\" else -0.07) + (0.08 if a == \"young\" else -0.05) + (0.10 if r == \"urban\" else -0.16)\n        blue = rng.random() < lean\n        habit = rng.random() < (0.38 + (0.22 if a == \"old\" else 0) + (0.12 if e == \"deg\" else 0))\n        p_vote = 0.18 + 0.70 * habit\n        says = max(1, min(10, round(10 * p_vote + 1.0 + rng.gauss(0, 1.5))))   # two weeks out: optimistic, and blind to what has not happened yet\n        late = False\n        if mobilize:                       # a late wave: non-habitual blue voters come out, some red habituals stay home\n            if blue and not habit: p_vote += 0.18; late = True\n            if (not blue) and habit: p_vote -= 0.08\n        votes = rng.random() < p_vote\n        base = 0.020 * (1.7 if e == \"deg\" else 0.8) * (1.3 if a == \"old\" else 0.8) * (1.15 if habit else 0.75)\n        party = 1.07 if blue else 0.93     # the hidden part: weights on age/education/area cannot see it\n        P.append(dict(cell=(e, a, r), blue=blue, habit=habit, votes=votes, late=late and votes,\n                      p_panel=base * party, p_anchor=min(0.9, 15 * base),\n                      says=says, recall_blue=blue))\n    return P\n\ndef truth(P):\n    v = [p for p in P if p[\"votes\"]]\n    return 100 * sum(p[\"blue\"] for p in v) / len(v)\n\ndef r_indicator(rates_by_cell, shares):\n    \"\"\"Spread of response rates between cells, as a coefficient of variation: CV = S(rho) / mean(rho).\n    0 = every cell answers at the same rate. (Schouten et al. pair the R-indicator, 1 - 2S, with this CV;\n    at response rates of 1-3% the R-indicator itself is always close to 1, so the CV is the readable one.)\"\"\"\n    m = sum(shares[c] * rates_by_cell[c] for c in shares)\n    var = sum(shares[c] * (rates_by_cell[c] - m) ** 2 for c in shares)\n    return math.sqrt(var) / m if m else 0\n\ndef shares_of(P):\n    out = {c: 0 for c in CELLS}\n    for p in P: out[p[\"cell\"]] += 1\n    return {c: v / len(P) for c, v in out.items()}\n\ndef field(P, attempts, rng, effort=None, phases=4, adaptive=False):\n    \"\"\"Fieldwork: `attempts` contact attempts in `phases` phases. Each attempt reaches a random person\n    in the chosen cell. Adaptive: after each phase, attempts move to the cells with the lowest response.\"\"\"\n    by_cell = {c: [p for p in P if p[\"cell\"] == c] for c in CELLS}\n    sh = shares_of(P)\n    tried = {c: 0 for c in CELLS}; got = {c: 0 for c in CELLS}; resp = []\n    alloc = {c: sh[c] for c in CELLS}\n    log = []\n    for ph in range(phases):\n        k = attempts // phases\n        for c in CELLS:\n            for _ in range(int(round(k * alloc[c]))):\n                p = rng.choice(by_cell[c]); tried[c] += 1\n                extra = 0.0 if not (adaptive and alloc[c] > sh[c]) else 0.8 * p[\"p_panel\"] / (1.07 if p[\"blue\"] else 0.93)   # a second channel / incentive where it is needed: it reaches the distrusting as often as the trusting\n                if rng.random() < p[\"p_panel\"] + extra:\n                    got[c] += 1; resp.append(p)\n        rates = {c: got[c] / tried[c] if tried[c] else 0 for c in CELLS}\n        R = r_indicator(rates, sh)\n        log.append(dict(phase=ph + 1, n=len(resp), R=round(R, 3)))\n        if adaptive:\n            inv = {c: sh[c] / max(rates[c], 1e-4) for c in CELLS}\n            s = sum(inv.values()); alloc = {c: inv[c] / s for c in CELLS}\n    return resp, log, tried\n\ndef rake(resp, P, keys=(0, 1, 2), rounds=12):\n    \"\"\"Iterative proportional fitting on the three cell variables, to the population margins.\"\"\"\n    w = [1.0] * len(resp); tp = len(P)\n    pops = [{} for _ in keys]\n    for p in P:\n        for j, k in enumerate(keys): pops[j][p[\"cell\"][k]] = pops[j].get(p[\"cell\"][k], 0) + 1\n    for _ in range(rounds):\n        for j, k in enumerate(keys):\n            pop = pops[j]; smp = {}\n            for i, p in enumerate(resp): smp[p[\"cell\"][k]] = smp.get(p[\"cell\"][k], 0) + w[i]\n            ts = sum(w)\n            for i, p in enumerate(resp):\n                v = p[\"cell\"][k]; w[i] *= (pop[v] / tp) / (smp[v] / ts)\n    return w\n\ndef estimate(resp, w, lv=lambda p: p[\"says\"] >= 9):\n    num = sum(wi for p, wi in zip(resp, w) if lv(p) and p[\"blue\"])\n    den = sum(wi for p, wi in zip(resp, w) if lv(p))\n    return 100 * num / den\n\ndef calibrate_to_anchor(resp, w, anchor):\n    \"\"\"Calibrate the panel's recalled past vote (blue/red), within each cell, to the anchor's.\"\"\"\n    w = list(w)\n    for c in CELLS:                                     # cell by cell: the anchor has ~100 people per cell\n        a = [p for p in anchor if p[\"cell\"] == c]\n        if len(a) < 30: continue\n        target = sum(p[\"recall_blue\"] for p in a) / len(a)\n        idx = [i for i, p in enumerate(resp) if p[\"cell\"] == c]\n        tot = sum(w[i] for i in idx)\n        b = sum(w[i] for i in idx if resp[i][\"recall_blue\"])\n        if 0 < b < tot:\n            for i in idx:\n                w[i] *= (target / (b / tot)) if resp[i][\"recall_blue\"] else ((1 - target) / (1 - b / tot))\n    return w\n\ndef within_gap(sample, P):\n    \"\"\"How much bluer the sample is than the population INSIDE each cell, averaged with population shares (points).\"\"\"\n    sh = shares_of(P); g = 0.0\n    for c in CELLS:\n        a = [p for p in sample if p[\"cell\"] == c]; b = [p for p in P if p[\"cell\"] == c]\n        if a: g += sh[c] * (sum(p[\"blue\"] for p in a) / len(a) - sum(p[\"blue\"] for p in b) / len(b))\n    return round(100 * g, 1)\n\nREPS = 8    # every lab is the average of 8 independent fieldworks, so one lucky draw does not decide\n\ndef _avg(rows):\n    out = {}\n    for k in rows[0]:\n        v = rows[0][k]\n        if not isinstance(v, (int, float)): out[k] = v; continue\n        m = sum(r[k] for r in rows) / len(rows)\n        out[k] = int(round(m)) if k in (\"n\", \"attempts\", \"anchor\", \"anchor_tries\") else round(m, 2 if k in (\"R\", \"R1\") else 1)\n    return out\n\ndef _one(P, rep, adaptive, anchor_n=0, second_wave=False, attempts=52000):\n    rng = random.Random(SEED + 100 + rep)\n    resp, log, tried = field(P, attempts - (8000 if anchor_n else 0), rng, adaptive=adaptive)   # the anchor costs ~8,000 panel attempts\n    w = rake(resp, P); out = {}\n    if anchor_n:\n        anc, tries = anchor_sample(P, random.Random(SEED + 200 + rep), anchor_n)\n        w = calibrate_to_anchor(resp, w, anc)\n        out.update(anchor=len(anc), anchor_tries=tries, anchor_gap=within_gap(anc, P), panel_gap=within_gap(resp, P))\n    lv = lambda p: p[\"says\"] >= 9\n    if second_wave:   # last-week re-contact: late movers now say 10; the wave reaches 70% of them\n        rr = random.Random(SEED + 300 + rep)\n        moved = {id(p) for p in resp if p[\"late\"] and rr.random() < 0.70}\n        lv = lambda p: p[\"says\"] >= 9 or id(p) in moved\n    est = estimate(resp, w, lv); t = truth(P)\n    out.update(truth=t, est=est, err=est - t, n=len(resp), R=log[-1][\"R\"], R1=log[0][\"R\"], attempts=sum(tried.values()))\n    return out\n\ndef anchor_sample(P, rng, n_target=800):\n    \"\"\"The anchor: random addresses, mail + phone + a visit. Slow and expensive, but the partisan gap in who answers is gone.\"\"\"\n    out = []; tries = 0\n    while len(out) < n_target and tries < 40000:\n        p = rng.choice(P); tries += 1\n        if rng.random() < p[\"p_anchor\"]: out.append(p)\n    return out, tries\n\ndef lab(kind, mobilize=False):\n    P = build_population(mobilize=mobilize)\n    cfg = {\"static\": (False, 0, False), \"responsive\": (True, 0, False), \"anchor\": (True, 800, False), \"two_waves\": (True, 800, True)}[kind]\n    return _avg([_one(P, k, *cfg) for k in range(REPS)])\n\ndef lab_static(mobilize=False): return lab(\"static\", mobilize)\ndef lab_responsive(mobilize=False): return lab(\"responsive\", mobilize)\ndef lab_anchor(mobilize=False, second_wave=False): return lab(\"two_waves\" if second_wave else \"anchor\", mobilize)\n\ndef run_all():\n    return {\"static\": lab_static(), \"responsive\": lab_responsive(), \"anchor\": lab_anchor(),\n            \"mobilize_one_wave\": lab_anchor(mobilize=True), \"mobilize_static\": lab_static(mobilize=True),\n            \"mobilize_two_waves\": lab_anchor(mobilize=True, second_wave=True)}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: static | responsive | anchor | mobilize.\"\"\"\n    ev, ck = [], []\n    if sc == \"static\":\n        r = lab_static()\n        ev += [_ev(\"F\", \"P\", \"attempts\", f\"{r['attempts']:,} contact attempts, spread like the population, in 4 phases\", f\"{r['attempts']:,} ניסיונות\"),\n               _ev(\"P\", \"M\", \"answers\", f\"{r['n']} people answered (~{100*r['n']/r['attempts']:.1f}%)\", f\"{r['n']} ענו\"),\n               _ev(\"M\", \"M\", \"R\", f\"spread of response rates between cells (CV) at the end: {r['R']} (0 = every cell answers at the same rate)\", f\"CV={r['R']}\", bad=r['R'] > 0.3),\n               _ev(\"M\", \"E\", \"rake\", f\"raked to age, education and area: estimate {r['est']}% blue among likely voters\", f\"{r['est']}%\"),\n               _ev(\"E\", \"E\", \"error\", f\"truth {r['truth']}%: error {r['err']:+} points, all of it from who answers inside each cell\", f\"{r['err']:+} נק'\", bad=abs(r['err']) > 1.5)]\n        ck += [[\"poll_runs\", r[\"n\"] > 500], [\"bias_measured\", True]]\n    elif sc == \"responsive\":\n        s = lab_static(); r = lab_responsive()\n        ev += [_ev(\"F\", \"P\", \"phase1\", f\"phase 1: same as always; CV = {r['R1']}\", f\"CV={r['R1']}\"),\n               _ev(\"M\", \"A\", \"realloc\", \"every 6 hours: attempts move to the cells that answer least, with a second channel there\", \"מעבירים מאמץ\"),\n               _ev(\"A\", \"P\", \"phases\", f\"after 4 phases: CV {r['R1']} -> {r['R']} (static ends at {s['R']}); {r['n']} answered vs {s['n']}\", f\"CV={r['R']}\", ok=r[\"R\"] < s[\"R\"]),\n               _ev(\"M\", \"E\", \"rake\", f\"estimate {r['est']}% vs truth {r['truth']}%: error {r['err']:+} (static: {s['err']:+})\", f\"{r['err']:+} נק'\", ok=abs(r['err']) < abs(s['err'])),\n               _ev(\"E\", \"E\", \"limit\", \"the cells now answer evenly, but INSIDE each cell blue still answers more: weights on cells cannot see that\", \"החלק שנשאר\", bad=True)]\n        ck += [[\"R_improves\", r[\"R\"] < s[\"R\"]], [\"error_shrinks\", abs(r[\"err\"]) < abs(s[\"err\"])], [\"same_budget\", True]]\n    elif sc == \"anchor\":\n        s = lab_static(); r = lab_anchor()\n        ev += [_ev(\"F\", \"N\", \"anchor\", f\"a random anchor: {r['anchor']} people from {r['anchor_tries']} addresses, with mail, phone and a visit\", f\"{r['anchor']} בעוגן\"),\n               _ev(\"N\", \"N\", \"gap\", f\"inside the cells, the anchor is {r['anchor_gap']:+} points bluer than the population; the panel is {r['panel_gap']:+}\", f\"{r['anchor_gap']:+}\", ok=abs(r[\"anchor_gap\"]) < abs(r[\"panel_gap\"])),\n               _ev(\"N\", \"M\", \"calib\", \"the panel's recalled past vote, cell by cell, is calibrated to the anchor's\", \"כיול לעוגן\", ok=True),\n               _ev(\"M\", \"E\", \"est\", f\"estimate {r['est']}% vs truth {r['truth']}%: error {r['err']:+} (static {s['err']:+})\", f\"{r['err']:+} נק'\", ok=abs(r[\"err\"]) < 1.5)]\n        ck += [[\"anchor_small_gap\", abs(r[\"anchor_gap\"]) < abs(r[\"panel_gap\"])], [\"error_under_1_5\", abs(r[\"err\"]) < 1.5]]\n    elif sc == \"mobilize\":\n        s = lab_static(mobilize=True); one = lab_anchor(mobilize=True); two = lab_anchor(mobilize=True, second_wave=True)\n        ev += [_ev(\"F\", \"P\", \"late\", f\"a late mobilisation: non-habitual blue voters turn out; truth is now {one['truth']}% blue\", f\"{one['truth']}%\"),\n               _ev(\"M\", \"E\", \"static\", f\"static poll: {s['est']}% (error {s['err']:+}); it looks closer only because two errors cancel: too blue in who answers, too red in who is counted as a likely voter\", f\"{s['err']:+}\", bad=True),\n               _ev(\"M\", \"E\", \"one\", f\"Second Call, one wave two weeks out: {one['est']}% (error {one['err']:+}); the late movers still said 'maybe'\", f\"{one['err']:+}\", bad=abs(one['err']) > 1.5),\n               _ev(\"W\", \"M\", \"two\", f\"a short second wave in the last week reaches 70% of the late movers: {two['est']}% (error {two['err']:+})\", f\"{two['err']:+}\", ok=abs(two['err']) < abs(one['err'])),\n               _ev(\"E\", \"E\", \"left\", \"what is left: the 30% who were not reached again, and anyone who decided on the day itself\", \"מה שנשאר\", bad=True)]\n        ck += [[\"second_wave_helps\", abs(two[\"err\"]) < abs(one[\"err\"])], [\"late_gap_measured\", True]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1, default=str))\n"});
